function patternHollowSquare(n) {
  let rows = [];
  for (let r = 0; r < n; r++) {
    let row = '';
    for (let c = 0; c < n; c++) {
      if (r === 0 || r === n - 1 || c === 0 || c === n - 1) {
        row += '*';
      } else {
        row += ' ';
      }
    }
    rows.push(row);
  }
  return rows.join('\n');
}

