function patternHollowSquare(n) {
  if (n === 1) return '*';
  let rows = [];
  const full = '*'.repeat(n);
  const middle = '*' + ' '.repeat(n - 2) + '*';
  for (let r = 0; r < n; r++) {
    if (r === 0 || r === n - 1) {
      rows.push(full);
    } else {
      rows.push(middle);
    }
  }
  return rows.join('\n');
}
